namespace {using namespace ii::gui;void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
template<class T>T take(ii::core::Result<T> r){if(!r)throw std::runtime_error(r.error().message);return std::move(*r);}void good(ii::core::Result<void> r){if(!r)throw std::runtime_error(r.error().message);}
using Id=std::variant<std::int64_t,std::string>;enum class ErrorCode{invalid,not_found,wrong_thread,exhausted};struct Error{ErrorCode code;std::string message;};template<class T>using Result=std::expected<T,Error>;struct Command{void invoke(const Id&)const{}};
struct Item{std::optional<Id> id;std::string icon_name,text,accessibility_name;bool enabled=true,visible=true,selected=false;std::shared_ptr<const Command> command;friend bool operator==(const Item&,const Item&)=default;};
struct Selection{Id id;std::size_t index=0;friend bool operator==(const Selection&,const Selection&)=default;};struct Snapshot{std::vector<Item> items;std::vector<Id> ids;std::optional<Selection> active;std::uint64_t revision=0;};struct Activation{Selection selection;bool changed=false;std::shared_ptr<const Command> command;};enum class Direction{previous,next,first,last};
struct ModelPolicy{using Item=::Item;using Id=::Id;using Snapshot=::Snapshot;using Selection=::Selection;using Activation=::Activation;using Direction=::Direction;using Error=::Error;using ErrorCode=::ErrorCode;template<class T>using Result=::Result<T>;static bool valid_text(std::string_view v){return v.find('\0')==v.npos&&ii::core::valid_utf8(v);}};
struct Appearance{double width=200,height=30,icon_size=16,font_size=12,corner_radius=8,background_opacity=0;bool enabled=true;WidgetColor background{};int palette=0;friend bool operator==(const Appearance&,const Appearance&)=default;};
struct Input{std::vector<Item> items;std::optional<Id> active_id;Appearance appearance;std::shared_ptr<const void> icon_source;std::int64_t icon_revision=0;friend bool operator==(const Input&,const Input&)=default;};
struct Rect{double x=0,y=0,width=0,height=0;};struct Geometry{double width=0,height=0;std::vector<Rect> slots;};struct Layout{static bool validate(const Appearance&){return true;}static std::optional<Geometry> geometry(const Snapshot& s,const Appearance& a,const std::vector<double>&){Geometry g{a.width,a.height,{}};for(std::size_t i=0;i<s.items.size();++i)g.slots.push_back({double(i)*40,0,40,a.height});return g;}};
enum class Tone{normal,borderless};struct ButtonConfig{Id id;std::string text,accessibility_name;bool enabled=true,visible=true,has_icon=false;double width=1,height=1,icon_size=1,corner_radius=0,font_size=12;int palette=0;Tone tone=Tone::normal;};struct ButtonInput{ButtonConfig configuration;std::shared_ptr<const RasterImage> icon;};struct ButtonModel{static bool validate(const ButtonConfig&){return true;}};
struct ButtonCallbacks{std::function<void()> clicked;};struct Button{Widget w;static ii::core::Result<Button> create(WidgetBuilder& b,Widget parent,std::string_view id,ButtonInput,ButtonCallbacks cb){auto v=b.action_surface(parent,id,{},std::move(cb.clicked));if(!v)return std::unexpected(v.error());return Button{*v};}Widget root()const{return w;}ii::core::Result<void> set_options(ButtonInput){return {};}};
struct Cache{inline static std::vector<std::weak_ptr<int>> retained;std::shared_ptr<int> marker=std::make_shared<int>(1);Cache(){retained.push_back(marker);}ii::core::Result<std::shared_ptr<const RasterImage>> resolve(std::string_view,std::shared_ptr<const void>,double){return rgba_image(1,1,{255,255,255,255});}};
struct Callbacks{std::function<void(const Selection&)> active_changed,triggered;};struct Policy{using Input=::Input;using Model=BasicHierarchyToolbar<ModelPolicy>;using Layout=::Layout;using ButtonModel=::ButtonModel;using Button=::Button;using ButtonInput=::ButtonInput;using Image=RasterImage;using ButtonTone=Tone;using IconCache=Cache;using Id=::Id;using Snapshot=::Snapshot;using Selection=::Selection;using Error=::Error;using ErrorCode=::ErrorCode;using Direction=::Direction;using Geometry=::Geometry;using Rect=::Rect;using Color=WidgetColor;using Callbacks=::Callbacks;};
}
int main(){using View=ii::gui::BasicNativeHierarchyToolbar<Policy>;auto tree=std::make_shared<detail::WidgetState>([](ii::runtime::Task t){t();});auto host=take(tree->content_host({},"host",{200,30}));Input in;in.items.resize(2);in.items[0].id=std::string("a");in.items[0].text="A";in.items[1].id=std::string("b");in.items[1].text="B";auto owner=std::make_shared<int>(1);std::weak_ptr<int> weak=owner;std::optional<View> view;int activated=0;
 good(host.set_content([&](WidgetBuilder& b)->ii::core::Result<void>{Callbacks cb;cb.triggered=[&,held=owner](const Selection&){++activated;};auto v=View::create(b,{},"toolbar",in,std::move(cb));if(!v)return std::unexpected(v.error());view=*v;return {};}));owner.reset();(void)take(tree->drawing_snapshot({200,30}));good(take(view->slot(Id{std::string("b")})).activate());check(activated==1&&take(view->snapshot())->active->id==Id{std::string("b")},"Toolbar activation failed");good(host.clear_content());for(const auto& item:Cache::retained)check(item.expired(),"Toolbar retained icon cache");check(weak.expired()&&!view->snapshot(),"Toolbar retained callback or remained live");tree->close();}
